<?php

declare(strict_types=1);

namespace Database\Seeders;

use Illuminate\Database\Seeder;
use Illuminate\Support\Facades\DB;
use RuntimeException;

/**
 * Datos territoriales de Bolivia incorporados en PHP. No requiere CSV.
 * IMPORTANTE: diseñado para tablas bo_* VACÍAS antes de la primera ejecución.
 * IDs fijos garantizan las relaciones y permiten repetir el seeder por upsert.
 * No usar si ya existen registros con IDs coincidentes en estas tablas.
 */
class BoliviaTerritorialSeeder extends Seeder
{
    public function run(): void
    {
        DB::transaction(function (): void {
            foreach ($this->datasets() as $table => $dataset) {
                $columns = $dataset['columns'];
                foreach (array_chunk($dataset['rows'], 300) as $chunk) {
                    $now = now();
                    $records = [];
                    foreach ($chunk as $values) {
                        $row = array_combine($columns, $values);
                        $row['created_at'] = $now;
                        $row['updated_at'] = $now;
                        $row['deleted_at'] = null;
                        $records[] = $row;
                    }
                    $pk = $columns[0];
                    DB::table($table)->upsert(
                        $records,
                        [$pk],
                        array_values(array_diff(array_keys($records[0]), [$pk, 'created_at']))
                    );
                }
            }
        });
    }

